  `type` enum('multiple_choice','true_false','short_answer') NOT NULL DEFAULT 'multiple_choice',
  `options` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`options`)),
  `correct_option` int(11) DEFAULT NULL,
  `correct_answer` text DEFAULT NULL,
  `explanation` text DEFAULT NULL,
  `points` int(11) DEFAULT 10,
  `sort_order` int(11) DEFAULT 0,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Dumping data for table `internship_quiz_questions`
--

INSERT INTO `internship_quiz_questions` (`id`, `lesson_id`, `question`, `type`, `options`, `correct_option`, `correct_answer`, `explanation`, `points`, `sort_order`, `created_at`, `updated_at`) VALUES
(1265, 941, 'What is the purpose of the &lt;head&gt; section in HTML?', 'multiple_choice', '[\"Stores visible content\",\"Contains metadata like the page title\",\"Displays images\",\"Creates links\"]', 0, NULL, 'The &lt;head&gt; holds metadata such as the page title, which appears in the browser tab.', 10, 1, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1266, 941, 'Which tag creates a hyperlink?', 'multiple_choice', '[\"&lt;link&gt;\",\"&lt;a&gt;\",\"&lt;href&gt;\",\"&lt;url&gt;\"]', 0, NULL, 'The &lt;a&gt; tag defines a hyperlink, with the destination specified in the href attribute.', 10, 2, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1267, 941, 'How do you add an image to an HTML page?', 'multiple_choice', '[\"&lt;image&gt;\",\"&lt;img&gt;\",\"&lt;picture&gt;\",\"&lt;src&gt;\"]', 0, NULL, 'The &lt;img&gt; tag is used to embed images, with the source specified in the src attribute.', 10, 3, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1268, 941, 'Which element is used for unordered lists?', 'multiple_choice', '[\"&lt;ol&gt;\",\"&lt;ul&gt;\",\"&lt;li&gt;\",\"&lt;list&gt;\"]', 0, NULL, '&lt;ul&gt; creates unordered (bulleted) lists, while &lt;ol&gt; is for ordered (numbered) lists.', 10, 4, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1269, 941, 'What does the \'alt\' attribute in &lt;img&gt; do?', 'multiple_choice', '[\"Specifies image size\",\"Describes the image for accessibility\",\"Sets the image color\",\"Links to another page\"]', 0, NULL, 'The alt attribute provides alternative text for images, shown if the image cannot load or for screen readers.', 10, 5, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1270, 941, 'Which tag is the largest heading?', 'multiple_choice', '[\"&lt;h6&gt;\",\"&lt;h1&gt;\",\"&lt;h&gt;\",\"&lt;heading&gt;\"]', 0, NULL, '&lt;h1&gt; is the largest and most important heading, typically used once per page.', 10, 6, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1271, 941, 'How do you create a table row?', 'multiple_choice', '[\"&lt;tr&gt;\",\"&lt;td&gt;\",\"&lt;th&gt;\",\"&lt;row&gt;\"]', 0, NULL, 'The &lt;tr&gt; tag defines a table row, containing cells like &lt;td&gt; or &lt;th&gt;.', 10, 7, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1272, 941, 'What happens if you forget to close a tag?', 'multiple_choice', '[\"The browser crashes\",\"The page doesn\\u2019t load\",\"The browser guesses where it ends\",\"Nothing\"]', 0, NULL, 'Browsers try to fix missing closing tags, but this can cause unexpected layout issues.', 10, 8, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1273, 941, 'Which tag is used for a paragraph?', 'multiple_choice', '[\"&lt;p&gt;\",\"&lt;para&gt;\",\"&lt;paragraph&gt;\",\"&lt;text&gt;\"]', 0, NULL, 'The &lt;p&gt; tag defines a paragraph of text.', 10, 9, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1274, 941, 'Which attribute specifies the link destination?', 'multiple_choice', '[\"link\",\"to\",\"href\",\"url\"]', 0, NULL, 'The href attribute in &lt;a&gt; tags defines the destination URL of the hyperlink.', 10, 10, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1275, 948, 'What is the purpose of the \'for\' attribute in a label?', 'multiple_choice', '[\"A) Connects label to input\",\"B) Sets font size\",\"C) Adds placeholder text\",\"D) Makes field required\"]', 0, NULL, 'The \'for\' attribute links a label to its corresponding input field using the field\'s ID', 10, 1, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1276, 948, 'Which attribute makes a field mandatory?', 'multiple_choice', '[\"A) required\",\"B) placeholder\",\"C) validate\",\"D) mandatory\"]', 0, NULL, 'The required attribute ensures users must fill in the field before submitting', 10, 2, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1277, 948, 'What does the \'pattern\' attribute do?', 'multiple_choice', '[\"A) Sets text alignment\",\"B) Adds keyboard shortcuts\",\"C) Defines regex validation\",\"D) Changes font color\"]', 0, NULL, 'Pattern uses regular expressions to define custom validation rules', 10, 3, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1278, 948, 'Which form method is more secure for sensitive data?', 'multiple_choice', '[\"A) GET\",\"B) POST\",\"C) PUT\",\"D) DELETE\"]', 0, NULL, 'POST sends data in the request body, making it more secure than GET which shows data in URL', 10, 4, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1279, 948, 'What happens when you click a submit button?', 'multiple_choice', '[\"A) Form resets\",\"B) Page refreshes\",\"C) Data is sent to server\",\"D) Browser closes\"]', 0, NULL, 'Submit buttons send form data to the server address specified in the action attribute', 10, 5, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1280, 948, 'Which attribute prevents browser validation?', 'multiple_choice', '[\"A) novalidate\",\"B) novalue\",\"C) validateoff\",\"D) skipvalidate\"]', 0, NULL, 'The novalidate attribute disables built-in HTML5 form validation', 10, 6, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1281, 948, 'What is CSRF protection?', 'multiple_choice', '[\"A) Password encryption\",\"B) Anti-spam measure\",\"C) Protection against fake form submissions\",\"D) File compression\"]', 0, NULL, 'CSRF tokens help prevent attackers from using your form without your knowledge', 10, 7, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1282, 948, 'Which input type has built-in email validation?', 'multiple_choice', '[\"A) text\",\"B) password\",\"C) email\",\"D) url\"]', 0, NULL, 'The email input type automatically checks for proper email format', 10, 8, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1283, 948, 'What should you use for multi-line text input?', 'multiple_choice', '[\"A) input with type=\'text\'\",\"B) textarea\",\"C) select\",\"D) checkbox\"]', 0, NULL, 'The textarea element allows users to enter multiple lines of text', 10, 9, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1284, 948, 'What is the best practice for form security?', 'multiple_choice', '[\"A) Never use HTTPS\",\"B) Always show error messages\",\"C) Validate on server side only\",\"D) Use both client and server validation\"]', 0, NULL, 'Client validation improves UX, but server validation is essential for security', 10, 10, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1285, 955, 'What does the CSS property \'display: none;\' do?', 'multiple_choice', '[\"Hides the element but keeps its space\",\"Hides the element and removes it from the layout flow\",\"Makes the element transparent\",\"Makes the element visible\"]', 0, NULL, '\'display: none;\' removes the element from the layout flow, so it doesn\'t take up space.', 10, 1, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1286, 955, 'Which CSS property hides an element but keeps its space reserved?', 'multiple_choice', '[\"display: hidden\",\"visibility: hidden\",\"opacity: 0\",\"display: none\"]', 0, NULL, '\'visibility: hidden\' hides the element while maintaining its space in the layout.', 10, 2, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1287, 955, 'Which value of the \'opacity\' property makes an element 50% transparent?', 'multiple_choice', '[\"0.5\",\"50%\",\"0.05\",\"5%\"]', 0, NULL, 'Opacity values range from 0.0 (fully transparent) to 1.0 (fully opaque). 0.5 means 50% transparency.', 10, 3, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1288, 955, 'Which display value makes an element behave like a block-level element?', 'multiple_choice', '[\"inline\",\"block\",\"inline-block\",\"none\"]', 0, NULL, '\'display: block\' makes an element start on a new line and take up the full width available.', 10, 4, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1289, 955, 'Which CSS property allows you to create table-like layouts without using HTML tables?', 'multiple_choice', '[\"table-style\",\"display: table\",\"table-layout\",\"visibility: table\"]', 0, NULL, '\'display: table\' enables table-like layouts using CSS without HTML table elements.', 10, 5, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1290, 955, 'What is the default display value for a <div> element?', 'multiple_choice', '[\"block\",\"inline\",\"inline-block\",\"none\"]', 0, NULL, '<div> elements are block-level by default, meaning they start on a new line and take full width.', 10, 6, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1291, 955, 'Which display value allows elements to sit next to each other horizontally?', 'multiple_choice', '[\"block\",\"inline\",\"flex\",\"grid\"]', 0, NULL, '\'display: inline\' places elements next to each other horizontally, unlike block elements which stack vertically.', 10, 7, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1292, 955, 'What does \'display: inline-block\' do?', 'multiple_choice', '[\"Makes elements block-level only\",\"Makes elements inline only\",\"Combines inline and block behaviors\",\"Hides the element\"]', 0, NULL, '\'display: inline-block\' makes elements sit inline but allows setting width, height, and margins.', 10, 8, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1293, 955, 'Which property can make an element invisible but still take up space?', 'multiple_choice', '[\"display: none\",\"visibility: hidden\",\"opacity: 0\",\"All of the above\"]', 0, NULL, '\'visibility: hidden\' hides the element while keeping its space in the layout.', 10, 9, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1294, 955, 'Which display value is used to create table cells in CSS table layouts?', 'multiple_choice', '[\"table-row\",\"table-cell\",\"table-column\",\"table-header\"]', 0, NULL, '\'display: table-cell\' makes an element behave like a table cell within a CSS table layout.', 10, 10, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1295, 959, 'What is the primary purpose of CSS preprocessors like Sass and Less?', 'multiple_choice', '[\"A. To add more HTML elements to a website\",\"B. To write CSS code more efficiently and manage complexity\",\"C. To create dynamic web pages without using JavaScript\",\"D. To reduce the file size of CSS files\"]', 0, NULL, 'CSS preprocessors are designed to simplify and automate the process of writing CSS code, making it easier to manage complex styles and reuse code.', 10, 1, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1296, 959, 'Which of the following is an example of a CSS framework?', 'multiple_choice', '[\"A. Font Awesome\",\"B. Bootstrap\",\"C. Material Design\",\"D. All of the above\"]', 0, NULL, 'CSS frameworks like Bootstrap and Tailwind CSS provide pre-designed UI components and layouts to speed up development.', 10, 2, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1297, 959, 'What is the main difference between Sass and Less?', 'multiple_choice', '[\"A. Sass is more complex than Less\",\"B. Less is more complex than Sass\",\"C. Sass is designed for server-side rendering, while Less is designed for client-side rendering\",\"D. Sass uses a different syntax than Less\"]', 0, NULL, 'Sass and Less are both CSS preprocessors, but Sass uses a syntax that is more similar to CSS than Less, which uses a syntax that is more similar to CSS but with some differences.', 10, 3, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1298, 959, 'Which of the following is a popular CSS framework that uses a utility-first approach?', 'multiple_choice', '[\"A. Bootstrap\",\"B. Tailwind CSS\",\"C. Material Design\",\"D. Foundation\"]', 0, NULL, 'Tailwind CSS is a popular CSS framework that uses a utility-first approach, which means that styles are applied to HTML elements using utility classes rather than custom classes.', 10, 4, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1299, 959, 'Why would you use a CSS framework in a project?', 'multiple_choice', '[\"A. To add more JavaScript functionality\",\"B. To speed up development and create a consistent design\",\"C. To reduce the file size of CSS files\",\"D. To add more HTML elements to a website\"]', 0, NULL, 'CSS frameworks are designed to speed up development and create a consistent design by providing pre-designed UI components and layouts.', 10, 5, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1300, 959, 'What is the purpose of using a CSS preprocessor like Sass in a project?', 'multiple_choice', '[\"A. To add more JavaScript functionality\",\"B. To write CSS code more efficiently and manage complexity\",\"C. To reduce the file size of CSS files\",\"D. To add more HTML elements to a website\"]', 0, NULL, 'CSS preprocessors like Sass are designed to simplify and automate the process of writing CSS code, making it easier to manage complex styles and reuse code.', 10, 6, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1301, 959, 'Which of the following is an example of a CSS framework that uses a component-based approach?', 'multiple_choice', '[\"A. Tailwind CSS\",\"B. Bootstrap\",\"C. Material Design\",\"D. Foundation\"]', 0, NULL, 'Bootstrap is a popular CSS framework that uses a component-based approach, which means that UI components are built using custom classes and HTML elements.', 10, 7, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1302, 959, 'Why would you use a CSS preprocessor like Less in a project?', 'multiple_choice', '[\"A. To add more JavaScript functionality\",\"B. To write CSS code more efficiently and manage complexity\",\"C. To reduce the file size of CSS files\",\"D. To add more HTML elements to a website\"]', 0, NULL, 'CSS preprocessors like Less are designed to simplify and automate the process of writing CSS code, making it easier to manage complex styles and reuse code.', 10, 8, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1303, 959, 'What is the main benefit of using a CSS framework in a project?', 'multiple_choice', '[\"A. To add more JavaScript functionality\",\"B. To speed up development and create a consistent design\",\"C. To reduce the file size of CSS files\",\"D. To add more HTML elements to a website\"]', 0, NULL, 'CSS frameworks are designed to speed up development and create a consistent design by providing pre-designed UI components and layouts.', 10, 9, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1304, 959, 'Which of the following is a popular CSS framework that is designed for responsive web design?', 'multiple_choice', '[\"A. Material Design\",\"B. Foundation\",\"C. Tailwind CSS\",\"D. Bootstrap\"]', 0, NULL, 'Bootstrap is a popular CSS framework that is designed for responsive web design, making it easy to create mobile-friendly and tablet-friendly websites.', 10, 10, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1305, 969, 'What is the main benefit of organizing code into modules in JavaScript?', 'multiple_choice', '[\"A\",\"B\",\"C\",\"D\"]', 0, NULL, 'Organizing code into modules improves code readability and maintainability by breaking down large codebases into smaller, reusable pieces.', 10, 1, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1306, 969, 'Which of the following is a performance optimization technique in JavaScript?', 'multiple_choice', '[\"A\",\"B\",\"C\",\"D\"]', 0, NULL, 'Avoiding unnecessary DOM manipulations and using the `requestAnimationFrame` function can improve the performance of JavaScript applications.', 10, 2, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1307, 969, 'What is a common security consideration when using JavaScript?', 'multiple_choice', '[\"A\",\"B\",\"C\",\"D\"]', 0, NULL, 'Using secure protocols such as HTTPS to prevent eavesdropping and tampering is a common security consideration when using JavaScript.', 10, 3, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1308, 969, 'What is the purpose of code review in JavaScript development?', 'multiple_choice', '[\"A\",\"B\",\"C\",\"D\"]', 0, NULL, 'Code review helps to identify and fix bugs, improve code quality, and ensure that best practices are followed.', 10, 4, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1309, 969, 'Which of the following is a common mistake to avoid in JavaScript?', 'multiple_choice', '[\"A\",\"B\",\"C\",\"D\"]', 0, NULL, 'Using `eval()` function can pose a security risk and should be avoided in favor of safer alternatives.', 10, 5, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1310, 969, 'How can you improve the performance of a JavaScript application?', 'multiple_choice', '[\"A\",\"B\",\"C\",\"D\"]', 0, NULL, 'Minimizing the use of synchronous code and using asynchronous programming techniques can improve the performance of a JavaScript application.', 10, 6, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1311, 969, 'What is the purpose of testing in JavaScript development?', 'multiple_choice', '[\"A\",\"B\",\"C\",\"D\"]', 0, NULL, 'Testing helps to ensure that the code works as expected, catch bugs, and improve code quality.', 10, 7, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1312, 969, 'Which of the following is a best practice for writing readable code?', 'multiple_choice', '[\"A\",\"B\",\"C\",\"D\"]', 0, NULL, 'Using clear and concise variable names can improve the readability of code.', 10, 8, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1313, 969, 'What is a common security consideration when using JavaScript in a web application?', 'multiple_choice', '[\"A\",\"B\",\"C\",\"D\"]', 0, NULL, 'Validating user input to prevent cross-site scripting (XSS) attacks is a common security consideration when using JavaScript in a web application.', 10, 9, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1314, 969, 'How can you improve the maintainability of a JavaScript codebase?', 'multiple_choice', '[\"A\",\"B\",\"C\",\"D\"]', 0, NULL, 'Using modular code and following a consistent coding style can improve the maintainability of a JavaScript codebase.', 10, 10, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1315, 976, 'What is the primary purpose of using a front-end framework like Bootstrap or Tailwind CSS?', 'multiple_choice', '[\"A. To create a full-stack application\",\"B. To simplify the development of responsive web designs\",\"C. To build a web server\",\"D. To create a mobile app\"]', 0, NULL, 'Front-end frameworks like Bootstrap and Tailwind CSS are used to simplify the development of responsive web designs by providing pre-built UI components and layouts.', 10, 1, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1316, 976, 'Which of the following front-end frameworks is known for its component-based architecture and is often used for building complex web applications?', 'multiple_choice', '[\"A. Angular\",\"B. React\",\"C. Vue.js\",\"D. Ember.js\"]', 0, NULL, 'Angular is a popular front-end framework that is known for its component-based architecture and is often used for building complex web applications.', 10, 2, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1317, 976, 'What is the main difference between React and Angular in terms of their approach to component management?', 'multiple_choice', '[\"A. React uses a virtual DOM, while Angular uses a real DOM\",\"B. React uses a real DOM, while Angular uses a virtual DOM\",\"C. React uses a different framework for state management\",\"D. Angular is a full-stack framework, while React is a front-end framework\"]', 0, NULL, 'React uses a virtual DOM, while Angular uses a real DOM. This difference in approach affects how components are managed and updated in both frameworks.', 10, 3, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1318, 976, 'Which of the following front-end frameworks is known for its simplicity and ease of use, making it a popular choice for building small to medium-sized web applications?', 'multiple_choice', '[\"A. Vue.js\",\"B. React\",\"C. Angular\",\"D. Ember.js\"]', 0, NULL, 'Vue.js is a popular front-end framework that is known for its simplicity and ease of use, making it a popular choice for building small to medium-sized web applications.', 10, 4, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1319, 976, 'When choosing a front-end framework, what factor should be considered most important?', 'multiple_choice', '[\"A. Learning curve\",\"B. Community support\",\"C. Performance\",\"D. All of the above\"]', 0, NULL, 'All of the above factors (learning curve, community support, and performance) should be considered when choosing a front-end framework, as they can impact the success and maintainability of a project.', 10, 5, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1320, 976, 'Which of the following is a key benefit of using a front-end framework like Tailwind CSS?', 'multiple_choice', '[\"A. It provides pre-built UI components and layouts\",\"B. It allows for custom CSS development\",\"C. It is a full-stack framework\",\"D. It is a JavaScript library\"]', 0, NULL, 'Tailwind CSS is a front-end framework that provides pre-built UI components and layouts, making it easier to develop responsive web designs.', 10, 6, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1321, 976, 'What is the primary difference between Vue.js and React in terms of their approach to state management?', 'multiple_choice', '[\"A. Vue.js uses a virtual DOM, while React uses a real DOM\",\"B. Vue.js uses a real DOM, while React uses a virtual DOM\",\"C. Vue.js uses a different framework for state management\",\"D. Vue.js has a more extensive set of built-in features\"]', 0, NULL, 'Vue.js uses a virtual DOM, while React uses a real DOM. However, Vue.js has a more extensive set of built-in features for state management, including its reactivity system.', 10, 7, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1322, 976, 'Which of the following front-end frameworks is known for its two-way data binding and is often used for building complex web applications?', 'multiple_choice', '[\"A. Angular\",\"B. React\",\"C. Vue.js\",\"D. Ember.js\"]', 0, NULL, 'Angular is a popular front-end framework that is known for its two-way data binding and is often used for building complex web applications.', 10, 8, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1323, 976, 'When choosing a front-end framework, what should be considered in addition to the framework\'s features and performance?', 'multiple_choice', '[\"A. Learning curve and community support\",\"B. Only the framework\'s features\",\"C. Only the framework\'s performance\",\"D. Nothing else\"]', 0, NULL, 'In addition to the framework\'s features and performance, the learning curve and community support should also be considered when choosing a front-end framework.', 10, 9, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1324, 976, 'Which of the following is a key benefit of using a front-end framework like Bootstrap?', 'multiple_choice', '[\"A. It provides pre-built UI components and layouts\",\"B. It allows for custom CSS development\",\"C. It is a full-stack framework\",\"D. It is a JavaScript library\"]', 0, NULL, 'Bootstrap is a front-end framework that provides pre-built UI components and layouts, making it easier to develop responsive web designs.', 10, 10, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1325, 979, 'What does React Router do?', 'multiple_choice', '[\"Manages page reloads\",\"Controls which components show based on URL\",\"Styles web pages\",\"Handles server requests\"]', 0, NULL, 'React Router acts as a traffic director showing different components based on the URL', 10, 1, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1326, 979, 'Which component wraps your entire routing system?', 'multiple_choice', '[\"Route\",\"BrowserRouter\",\"Switch\",\"Link\"]', 0, NULL, 'BrowserRouter is the container that makes routing possible in your app', 10, 2, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1327, 979, 'What happens when you click a Link component?', 'multiple_choice', '[\"Page reloads\",\"URL changes without reloading\",\"Nothing happens\",\"Shows a popup\"]', 0, NULL, 'Links change the URL without reloading the whole page', 10, 3, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1328, 979, 'Which prop gets route parameters in a component?', 'multiple_choice', '[\"params\",\"route\",\"match\",\"url\"]', 0, NULL, 'The match object contains route parameters from the URL', 10, 4, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1329, 979, 'What does :id mean in a route path?', 'multiple_choice', '[\"It\'s a fixed string\",\"It\'s a parameter placeholder\",\"It means private route\",\"It\'s a styling class\"]', 0, NULL, 'Colons in routes mark dynamic parameters that can change', 10, 5, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1330, 979, 'What\'s the purpose of the Switch component?', 'multiple_choice', '[\"Styles navigation links\",\"Groups related routes\",\"Renders only the first matching route\",\"Handles server requests\"]', 0, NULL, 'Switch ensures only one route is shown at a time', 10, 6, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1331, 979, 'How do you redirect users in a navigation guard?', 'multiple_choice', '[\"Use history.push()\",\"Throw an error\",\"Change window.location\",\"Use Link component\"]', 0, NULL, 'history.push() changes the URL programmatically without reloading', 10, 7, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1332, 979, 'What\'s the best way to highlight active navigation links?', 'multiple_choice', '[\"CSS classes\",\"NavLink component\",\"JavaScript checks\",\"Route props\"]', 0, NULL, 'NavLink automatically adds active styles when its route matches', 10, 8, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1333, 979, 'What should you do for unmatched routes?', 'multiple_choice', '[\"Throw an error\",\"Show a 404 page\",\"Reload the app\",\"Ignore it\"]', 0, NULL, 'A catch-all route for unmatched paths improves user experience', 10, 9, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1334, 979, 'Where should you put your route definitions?', 'multiple_choice', '[\"In the main app component\",\"In a separate routes.js file\",\"In the index.html\",\"In CSS files\"]', 0, NULL, 'Route definitions usually go in your main app component or a dedicated routing file', 10, 10, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1335, 990, 'What is the primary purpose of a Database Management System (DBMS)?', 'multiple_choice', '[\"To manage data storage, retrieval, and security\",\"To manage computer networks\",\"To create web applications\",\"To design user interfaces\"]', 0, NULL, 'A DBMS centralizes data management, ensuring efficient storage, retrieval, and security.', 10, 1, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1336, 990, 'Which of the following is a relational database?', 'multiple_choice', '[\"MySQL\",\"MongoDB\",\"Redis\",\"Cassandra\"]', 0, NULL, 'MySQL is a relational database that uses SQL for querying structured data.', 10, 2, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1337, 990, 'What does a database schema describe?', 'multiple_choice', '[\"The structure and organization of a database\",\"The data stored in a database\",\"The queries executed on a database\",\"The users of a database\"]', 0, NULL, 'A schema defines tables, relationships, constraints, and other structural elements.', 10, 3, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1338, 990, 'In database modeling, what represents a real-world object or concept?', 'multiple_choice', '[\"Entity\",\"Attribute\",\"Relationship\",\"Index\"]', 0, NULL, 'An entity models real-world objects, like \'Customer\' or \'Product\', in a database.', 10, 4, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1339, 990, 'Which is a type of non-relational (NoSQL) database?', 'multiple_choice', '[\"MongoDB\",\"PostgreSQL\",\"Oracle\",\"SQL Server\"]', 0, NULL, 'MongoDB is a document-based NoSQL database for unstructured or semi-structured data.', 10, 5, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1340, 990, 'What is the first step in database design?', 'multiple_choice', '[\"Identifying entities and their attributes\",\"Creating tables and indexes\",\"Writing SQL queries\",\"Optimizing performance\"]', 0, NULL, 'Design begins by defining entities, their attributes, and relationships.', 10, 6, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1341, 990, 'What is the purpose of database normalization?', 'multiple_choice', '[\"To reduce data redundancy\",\"To increase data redundancy\",\"To simplify database queries\",\"To improve application performance\"]', 0, NULL, 'Normalization minimizes redundancy by organizing data into related tables.', 10, 7, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1342, 990, 'What is a primary key in a database table?', 'multiple_choice', '[\"A unique identifier for each record\",\"A field that can contain duplicate values\",\"A relationship between two tables\",\"A type of database index\"]', 0, NULL, 'A primary key uniquely identifies each row in a table.', 10, 8, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1343, 990, 'When is denormalization typically used?', 'multiple_choice', '[\"To improve read performance in complex queries\",\"To reduce data redundancy\",\"To enforce referential integrity\",\"To simplify database schema design\"]', 0, NULL, 'Denormalization adds redundancy to optimize read-heavy operations.', 10, 9, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1344, 990, 'Which normal form ensures each table has a primary key?', 'multiple_choice', '[\"First Normal Form (1NF)\",\"Second Normal Form (2NF)\",\"Third Normal Form (3NF)\",\"Boyce-Codd Normal Form (BCNF)\"]', 0, NULL, '1NF requires atomic values and a primary key for unique identification.', 10, 10, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1345, 997, 'What is the primary goal of a code review?', 'multiple_choice', '[\"Finding bugs\",\"Enforcing coding standards\",\"Checking documentation\",\"All of the above\"]', 0, NULL, 'Code reviews aim to improve code quality by finding bugs, ensuring consistency, and verifying documentation.', 10, 1, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1346, 997, 'Which of the following is a popular code testing framework for JavaScript?', 'multiple_choice', '[\"Jest\",\"Selenium\",\"JUnit\",\"PyTest\"]', 0, NULL, 'Jest is a widely used testing framework for JavaScript, while Selenium is for UI testing, JUnit for Java, and PyTest for Python.', 10, 2, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1347, 997, 'Unit testing focuses on testing which of the following?', 'multiple_choice', '[\"The entire system\",\"Individual functions or components\",\"User interfaces\",\"Databases\"]', 0, NULL, 'Unit testing verifies the correctness of individual functions or components in isolation.', 10, 3, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1348, 997, 'Integration testing is primarily used to test:', 'multiple_choice', '[\"Individual units in isolation\",\"The entire system\'s performance\",\"Interactions between components\",\"User interface elements\"]', 0, NULL, 'Integration testing ensures that multiple components or modules work together correctly.', 10, 4, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1349, 997, 'Which of the following is a best practice for code reviews?', 'multiple_choice', '[\"Keep reviews small and focused\",\"Assign reviews to only one person\",\"Avoid providing feedback\",\"Skip reviewing documentation\"]', 0, NULL, 'Small, focused reviews are easier to manage and lead to more effective feedback.', 10, 5, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1350, 997, 'What is a key benefit of code reviews?', 'multiple_choice', '[\"Catching bugs early\",\"Enforcing coding standards\",\"Improving code quality\",\"All of the above\"]', 0, NULL, 'Code reviews help identify issues early, ensure consistency, and enhance overall code quality.', 10, 6, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1351, 997, 'What does TDD stand for?', 'multiple_choice', '[\"Test-Driven Development\",\"Test-Driven Design\",\"Testing and Debugging Development\",\"Test-Driven Deployment\"]', 0, NULL, 'TDD (Test-Driven Development) is a practice where tests are written before the actual code.', 10, 7, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1352, 997, 'Which of the following is a code testing framework for Python?', 'multiple_choice', '[\"PyTest\",\"Selenium\",\"JUnit\",\"Mocha\"]', 0, NULL, 'PyTest is a popular testing framework for Python, while Selenium is for UI testing, JUnit for Java, and Mocha for JavaScript.', 10, 8, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1353, 997, 'Which of the following is a best practice for giving feedback during code reviews?', 'multiple_choice', '[\"Provide actionable and specific feedback\",\"Avoid giving any comments to save time\",\"Focus only on style over functionality\",\"Rush through the review process\"]', 0, NULL, 'Actionable and specific feedback helps developers understand and improve their code effectively.', 10, 9, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1354, 997, 'What is the purpose of a code review checklist?', 'multiple_choice', '[\"To ensure consistency and completeness in reviews\",\"To speed up the review process\",\"To ignore coding standards\",\"To reduce the need for testing\"]', 0, NULL, 'A checklist ensures that all critical aspects of the code are reviewed systematically.', 10, 10, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1355, 1004, 'What is the primary purpose of a CI/CD pipeline?', 'multiple_choice', '[\"To manually review code\",\"To automate build, test, and deploy processes\",\"To store database backups\",\"To monitor server uptime\"]', 0, NULL, 'A CI/CD pipeline automates the steps of building, testing, and deploying code so changes can be released quickly and reliably.', 10, 1, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1356, 1004, 'Which step typically occurs first in a CI pipeline?', 'multiple_choice', '[\"Deployment to production\",\"Running unit tests\",\"Building artifacts\",\"Monitoring metrics\"]', 0, NULL, 'The first step is usually building the code into artifacts before any tests are run.', 10, 2, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1357, 1004, 'In continuous deployment, when is code released to production?', 'multiple_choice', '[\"After manual approval\",\"After passing all automated tests\",\"Every Friday at 5pm\",\"Only after a release manager signs off\"]', 0, NULL, 'Continuous deployment releases code automatically once it passes all automated tests.', 10, 3, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1358, 1004, 'Which tool is commonly used for automated testing in CI?', 'multiple_choice', '[\"Jenkins\",\"Selenium\",\"Docker\",\"Git\"]', 0, NULL, 'Selenium is a popular framework for automating web UI tests, often integrated into CI pipelines.', 10, 4, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1359, 1004, 'What does \"monitoring\" in CI/CD refer to?', 'multiple_choice', '[\"Watching developers log in\",\"Tracking application performance after deployment\",\"Counting lines of code\",\"Reviewing commit messages\"]', 0, NULL, 'Monitoring tracks how the application behaves in production, detecting issues early.', 10, 5, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1360, 1004, 'Which service provides CI/CD pipelines as a cloud offering?', 'multiple_choice', '[\"GitHub Actions\",\"Microsoft Word\",\"Adobe Photoshop\",\"Slack\"]', 0, NULL, 'GitHub Actions offers cloud-based CI/CD workflows that run on GitHub-hosted runners.', 10, 6, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1361, 1004, 'Which of the following is NOT part of a typical CI pipeline?', 'multiple_choice', '[\"Static code analysis\",\"Manual QA testing\",\"Artifact publishing\",\"Code linting\"]', 0, NULL, 'Manual QA testing is usually done outside of the automated CI pipeline.', 10, 7, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1362, 1004, 'In a CD pipeline, what is a \"canary release\"?', 'multiple_choice', '[\"Deploying to all servers at once\",\"Deploying to a small subset of users first\",\"Rolling back all deployments\",\"Skipping tests\"]', 0, NULL, 'A canary release deploys to a few users or servers first to validate the new version before full rollout.', 10, 8, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1363, 1004, 'Which command is used to build a Docker image in a CI job?', 'multiple_choice', '[\"docker build\",\"docker run\",\"docker pull\",\"docker push\"]', 0, NULL, 'The docker build command creates a new image from a Dockerfile during a CI job.', 10, 9, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1364, 1004, 'Which metric is most useful for monitoring continuous deployment health?', 'multiple_choice', '[\"Number of commits per day\",\"Deployment frequency\",\"Lines of code added\",\"Number of open issues\"]', 0, NULL, 'Deployment frequency shows how often new changes reach production, indicating CI/CD effectiveness.', 10, 10, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1365, 1011, 'What is the primary purpose of a CI/CD pipeline?', 'multiple_choice', '[\"To manually test code\",\"To automate build, test, and deployment\",\"To write documentation\",\"To monitor user traffic\"]', 0, NULL, 'CI/CD pipelines automate the process of building, testing, and deploying code to reduce manual effort and speed up releases.', 10, 1, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1366, 1011, 'Which tool is commonly used for continuous integration on Windows environments?', 'multiple_choice', '[\"CircleCI\",\"GitLab CI\",\"Jenkins\",\"Travis CI\"]', 0, NULL, 'Jenkins is a widely used, platform‑agnostic CI tool that works well on Windows servers.', 10, 2, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1367, 1011, 'In CircleCI, which configuration file is used to define jobs and workflows?', 'multiple_choice', '[\".circleci\\/config.yml\",\"circleci.yml\",\".circleci\\/pipeline.yml\",\"config.json\"]', 0, NULL, 'CircleCI reads the .circleci/config.yml file to configure jobs, steps, and workflows.', 10, 3, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1368, 1011, 'What is a key benefit of automated testing in CI/CD?', 'multiple_choice', '[\"Slower builds\",\"Reduced manual QA effort\",\"More bugs\",\"Longer deployment time\"]', 0, NULL, 'Automated tests run quickly in the pipeline, freeing QA teams from repetitive manual testing.', 10, 4, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1369, 1011, 'Which of the following is a common scalability challenge in CI/CD?', 'multiple_choice', '[\"Limited version control\",\"Build queue bottlenecks\",\"Lack of documentation\",\"Excessive test coverage\"]', 0, NULL, 'When many jobs run simultaneously, build queues can become bottlenecks, delaying feedback.', 10, 5, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1370, 1011, 'How can security be integrated into CI/CD pipelines?', 'multiple_choice', '[\"Ignoring secrets\",\"Using environment variables securely\",\"Hardcoding passwords\",\"Manual code reviews only\"]', 0, NULL, 'Securely storing secrets as environment variables or vault entries keeps sensitive data out of source code.', 10, 6, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1371, 1011, 'What does the \"CD\" in CI/CD stand for?', 'multiple_choice', '[\"Continuous Development\",\"Continuous Deployment\",\"Code Delivery\",\"Continuous Design\"]', 0, NULL, 'CD refers to Continuous Deployment, the automated release of code to production.', 10, 7, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1372, 1011, 'Which feature of Jenkins allows you to schedule builds?', 'multiple_choice', '[\"Blue Ocean\",\"Pipeline\",\"Build Triggers\",\"Credentials\"]', 0, NULL, 'Build Triggers in Jenkins let you set cron‑style schedules for automated builds.', 10, 8, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1373, 1011, 'How might AI be used to improve CI/CD pipelines?', 'multiple_choice', '[\"Randomly selecting tests\",\"Predicting flaky tests\",\"Removing all tests\",\"Manual deployment\"]', 0, NULL, 'AI can analyze test results to predict flaky tests, reducing wasted build time.', 10, 9, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1374, 1011, 'What is a best practice when using CircleCI for deployments?', 'multiple_choice', '[\"Deploy directly from main branch\",\"Use separate deployment jobs with approvals\",\"Deploy without rollback strategy\",\"Disable caching\"]', 0, NULL, 'Separating deployment jobs and requiring approvals adds safety and rollback options.', 10, 10, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1375, 1018, 'What command is used to create a new branch in Git?', 'multiple_choice', '[\"git branch <branch-name>\",\"git checkout <branch-name>\",\"git create <branch-name>\",\"git new-branch <branch-name>\"]', 0, NULL, 'The \'git branch\' command creates a new branch but does not switch to it. \'git checkout -b\' is used to create and switch to a new branch in one step.', 10, 1, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1376, 1018, 'How do you switch to an existing branch in Git?', 'multiple_choice', '[\"git switch <branch-name>\",\"git checkout <branch-name>\",\"git change <branch-name>\",\"git move <branch-name>\"]', 0, NULL, 'The \'git checkout\' command switches to an existing branch. Newer versions of Git also support \'git switch\' for this purpose.', 10, 2, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1377, 1018, 'What command merges changes from one branch into the current branch?', 'multiple_choice', '[\"git merge <branch-name>\",\"git pull <branch-name>\",\"git combine <branch-name>\",\"git join <branch-name>\"]', 0, NULL, '\'git merge\' integrates changes from the specified branch into the current branch. Other commands like \'git pull\' fetch and merge from a remote repository.', 10, 3, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1378, 1018, 'What should you do after resolving merge conflicts in Git?', 'multiple_choice', '[\"git commit\",\"git merge --continue\",\"git add <resolved-file>\",\"All of the above\"]', 0, NULL, 'After resolving conflicts, you must stage the resolved files with \'git add\' and then commit the merge with \'git commit\'. \'git merge --continue\' is also valid after adding changes.', 10, 4, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1379, 1018, 'Which of the following is a common Git branching strategy?', 'multiple_choice', '[\"Git Flow\",\"Feature Commit\",\"Trunk-Based Deployment\",\"All of the above\"]', 0, NULL, 'Git Flow is a structured branching strategy. Trunk-Based Development is another strategy, but \'Feature Commit\' is not a standard term in this context.', 10, 5, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1380, 1018, 'What is a best practice for managing Git branches?', 'multiple_choice', '[\"Create a new branch for every feature\",\"Merge branches without testing\",\"Delete branches immediately after merging\",\"Use the same branch for all development\"]', 0, NULL, 'Creating a dedicated branch for each feature isolates changes and improves collaboration. Other options introduce risks like untested merges or shared branch conflicts.', 10, 6, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1381, 1018, 'What does the \'git pull\' command do?', 'multiple_choice', '[\"Fetches and merges changes from a remote repository\",\"Fetches changes but does not merge them\",\"Merges local changes into a remote repository\",\"Deletes local changes to match the remote\"]', 0, NULL, '\'git pull\' is shorthand for \'git fetch\' followed by \'git merge\', combining remote changes with the local branch.', 10, 7, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1382, 1018, 'What is the purpose of \'git rebase\'?', 'multiple_choice', '[\"To rewrite commit history and create a linear branch\",\"To merge branches with conflicts\",\"To delete old commits from history\",\"To rename a branch\"]', 0, NULL, '\'git rebase\' moves or combines commits, creating a linear history. It rewrites commit history, unlike \'git merge\' which preserves the original history.', 10, 8, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1383, 1018, 'What happens when you merge two branches with no conflicts?', 'multiple_choice', '[\"Git automatically creates a merge commit\",\"Git deletes the merged branch\",\"Git throws an error\",\"Git requires manual conflict resolution\"]', 0, NULL, 'When there are no conflicts, Git automatically creates a merge commit combining the histories of both branches.', 10, 9, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1384, 1018, 'What is the default branch name in Git when initializing a new repository?', 'multiple_choice', '[\"main\",\"master\",\"develop\",\"trunk\"]', 0, NULL, 'Modern Git versions default to \'main\' instead of \'master\' to promote inclusive language. This can be configured during repository initialization.', 10, 10, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1385, 1021, 'What is the primary purpose of unit testing in web development?', 'multiple_choice', '[\"A\",\"B\",\"C\",\"D\"]', 0, NULL, 'Unit testing is used to ensure individual components of the code work as expected, making it easier to identify and fix bugs.', 10, 1, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1386, 1021, 'Which of the following is an example of a debugging tool?', 'multiple_choice', '[\"A\",\"B\",\"C\",\"D\"]', 0, NULL, 'A browser\'s developer tools, such as the console and debugger, are useful for identifying and fixing errors.', 10, 2, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1387, 1021, 'What is integration testing used for?', 'multiple_choice', '[\"A\",\"B\",\"C\",\"D\"]', 0, NULL, 'Integration testing checks how different components of the code work together, ensuring they interact correctly.', 10, 3, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1388, 1021, 'Why is it essential to test for security vulnerabilities in web applications?', 'multiple_choice', '[\"A\",\"B\",\"C\",\"D\"]', 0, NULL, 'Testing for security vulnerabilities helps prevent potential attacks and protects user data.', 10, 4, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1389, 1021, 'What is a common error in web development that can be identified using debugging tools?', 'multiple_choice', '[\"A\",\"B\",\"C\",\"D\"]', 0, NULL, 'Typographical errors, such as missing or extra brackets, can cause syntax errors and be identified using debugging tools.', 10, 5, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1390, 1021, 'How often should you run unit tests on your code?', 'multiple_choice', '[\"A\",\"B\",\"C\",\"D\"]', 0, NULL, 'It\'s recommended to run unit tests frequently, especially after making changes to the code, to ensure everything still works as expected.', 10, 6, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1391, 1021, 'What is the purpose of using a testing framework?', 'multiple_choice', '[\"A\",\"B\",\"C\",\"D\"]', 0, NULL, 'A testing framework provides a structured way to write and run tests, making it easier to identify and fix bugs.', 10, 7, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1392, 1021, 'What is one technique used to identify and fix common errors?', 'multiple_choice', '[\"A\",\"B\",\"C\",\"D\"]', 0, NULL, 'Code review involves having another developer review your code to catch any errors or areas for improvement.', 10, 8, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1393, 1021, 'Why is it essential to test for security vulnerabilities in web applications?', 'multiple_choice', '[\"A\",\"B\",\"C\",\"D\"]', 0, NULL, 'Testing for security vulnerabilities helps prevent potential attacks and protects user data.', 10, 9, '2026-06-14 16:23:45', '2026-06-14 16:23:45'),
(1394, 1021, 'Which of the following is NOT a common error in web development?', 'multiple_choice', '[\"A\",\"B\",\"C\",\"D\"]', 0, NULL, 'Memory leaks are not typically considered a common error in web development, although they can be problematic.', 10, 10, '2026-06-14 16:23:45', '2026-06-14 16:23:45');

