--
-- Table structure for table `internship_reports`
--

CREATE TABLE `internship_reports` (
  `id` int(11) NOT NULL,
  `user_id` int(11) NOT NULL,
  `report_type` enum('progress','completion','performance') DEFAULT 'progress',
  `report_data` longtext DEFAULT NULL,
  `total_courses` int(11) DEFAULT 0,
  `completed_courses` int(11) DEFAULT 0,
  `total_topics` int(11) DEFAULT 0,
  `completed_topics` int(11) DEFAULT 0,
  `average_quiz_score` decimal(5,2) DEFAULT 0.00,
  `certificates_earned` int(11) DEFAULT 0,
  `overall_progress` decimal(5,2) DEFAULT 0.00,
  `generated_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `is_downloaded` tinyint(1) DEFAULT 0,
  `downloaded_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

