--
-- Table structure for table `offline_internship_applications`
--

CREATE TABLE `offline_internship_applications` (
  `id` int(11) UNSIGNED NOT NULL,
  `name` varchar(255) NOT NULL,
  `email` varchar(255) NOT NULL,
  `phone` varchar(20) NOT NULL,
  `college` varchar(255) DEFAULT NULL,
  `course` varchar(255) DEFAULT NULL,
  `year` varchar(50) DEFAULT NULL,
  `internship_type` varchar(255) NOT NULL COMMENT 'Web Development, Data Science, etc.',
  `duration` varchar(100) DEFAULT NULL COMMENT '1 month, 2 months, etc.',
  `message` text DEFAULT NULL,
  `is_contacted` tinyint(1) DEFAULT 0 COMMENT '0=Not Contacted, 1=Contacted',
  `is_enrolled` tinyint(1) DEFAULT 0 COMMENT '0=Not Enrolled, 1=Enrolled',
  `contacted_at` datetime DEFAULT NULL,
  `enrolled_at` datetime DEFAULT NULL,
  `notes` text DEFAULT NULL COMMENT 'Admin notes',
  `status` enum('pending','contacted','enrolled','rejected') DEFAULT 'pending',
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

