--
-- Table structure for table `referrals`
--

CREATE TABLE `referrals` (
  `id` int(11) UNSIGNED NOT NULL,
  `referrer_user_id` int(10) UNSIGNED NOT NULL COMMENT 'User who referred',
  `referred_user_id` int(10) UNSIGNED NOT NULL COMMENT 'User who signed up',
  `referral_code` varchar(20) NOT NULL,
  `status` enum('pending','completed','cancelled') DEFAULT 'pending',
  `signup_date` datetime DEFAULT current_timestamp(),
  `first_purchase_date` datetime DEFAULT NULL,
  `signup_discount_applied` decimal(10,2) DEFAULT 0.00,
  `created_at` timestamp NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_uca1400_ai_ci COMMENT='Track referral relationships';

